import pandas as pd

def clean(df):
    d = df.copy()
    for col in ['penguin_id', 'species', 'island', 'sex']:
        if col in d.columns:
            d[col] = d[col].astype('string').str.strip()
    if 'island' in d.columns:
        d['island'] = d['island'].replace({'Bisco': 'Biscoe'})
    if 'sex' in d.columns:
        d['sex'] = d['sex'].str.lower()
        d['sex'] = d['sex'].where(d['sex'].isin(['male', 'female']), pd.NA)
    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'body_mass_g', 'year']:
        if col in d.columns:
            d[col] = pd.to_numeric(d[col], errors='coerce')
    d = d.drop_duplicates()
    return d

def answer(df):
    d = clean(df)
    result = d.dropna(subset=['sex']).groupby('sex')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in result.items()}
